// Package server exposes a store.Store over HTTP.
package server

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"

	"kvhttp/internal/store"
)

const (
	// MaxKeyLen is the maximum key length in bytes.
	MaxKeyLen = 64
	// MaxValueLen is the maximum value size in bytes.
	MaxValueLen = 1 << 20

	kvPrefix = "/kv/"
)

// Handler routes requests to the key-value store.
//
// It deliberately does not use http.ServeMux: the mux cleans and redirects
// paths, whereas this API must reject malformed keys with 400.
type Handler struct {
	store *store.Store
}

// New returns a Handler backed by s.
func New(s *store.Store) *Handler {
	return &Handler{store: s}
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.ContentLength > MaxValueLen {
		w.Header().Set("Connection", "close")
		writeEmpty(w, http.StatusRequestEntityTooLarge)
		return
	}

	// Use the path as sent so that percent-escapes are never decoded into
	// otherwise valid key characters.
	path := r.URL.EscapedPath()
	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		writeBody(w, http.StatusOK, "text/plain", []byte("ok"))
	case path == "/kv":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		h.list(w)
	case strings.HasPrefix(path, kvPrefix):
		key := path[len(kvPrefix):]
		if !validKey(key) {
			writeEmpty(w, http.StatusBadRequest)
			return
		}
		h.key(w, r, key)
	default:
		writeEmpty(w, http.StatusNotFound)
	}
}

func (h *Handler) list(w http.ResponseWriter) {
	body, err := json.Marshal(h.store.Keys())
	if err != nil {
		writeEmpty(w, http.StatusInternalServerError)
		return
	}
	writeBody(w, http.StatusOK, "application/json", body)
}

func (h *Handler) key(w http.ResponseWriter, r *http.Request, key string) {
	switch r.Method {
	case http.MethodGet:
		val, ok := h.store.Get(key)
		if !ok {
			writeEmpty(w, http.StatusNotFound)
			return
		}
		writeBody(w, http.StatusOK, "application/octet-stream", val)
	case http.MethodPut:
		val, err := readBody(w, r)
		if err != nil {
			var tooLarge *http.MaxBytesError
			if errors.As(err, &tooLarge) {
				writeEmpty(w, http.StatusRequestEntityTooLarge)
			} else {
				writeEmpty(w, http.StatusBadRequest)
			}
			return
		}
		if h.store.Put(key, val) {
			writeEmpty(w, http.StatusCreated)
		} else {
			writeEmpty(w, http.StatusOK)
		}
	case http.MethodDelete:
		if h.store.Delete(key) {
			w.WriteHeader(http.StatusNoContent)
		} else {
			writeEmpty(w, http.StatusNotFound)
		}
	default:
		methodNotAllowed(w, http.MethodGet, http.MethodPut, http.MethodDelete)
	}
}

// readBody reads the full request body, enforcing MaxValueLen.
func readBody(w http.ResponseWriter, r *http.Request) ([]byte, error) {
	body := http.MaxBytesReader(w, r.Body, MaxValueLen)
	if r.ContentLength >= 0 {
		buf := make([]byte, r.ContentLength)
		if _, err := io.ReadFull(body, buf); err != nil {
			return nil, err
		}
		return buf, nil
	}
	return io.ReadAll(body)
}

// validKey reports whether k matches [A-Za-z0-9_-]{1,MaxKeyLen}.
func validKey(k string) bool {
	if len(k) == 0 || len(k) > MaxKeyLen {
		return false
	}
	for i := 0; i < len(k); i++ {
		c := k[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

func methodNotAllowed(w http.ResponseWriter, allowed ...string) {
	w.Header().Set("Allow", strings.Join(allowed, ", "))
	writeEmpty(w, http.StatusMethodNotAllowed)
}

func writeEmpty(w http.ResponseWriter, status int) {
	w.Header().Set("Content-Length", "0")
	w.WriteHeader(status)
}

func writeBody(w http.ResponseWriter, status int, contentType string, body []byte) {
	h := w.Header()
	h.Set("Content-Type", contentType)
	h.Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	_, _ = w.Write(body)
}

package server

import (
	"bytes"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"kvhttp/internal/store"
)

func do(t *testing.T, h http.Handler, method, target, body string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, target, strings.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func TestRoutes(t *testing.T) {
	h := New(store.New())
	steps := []struct {
		method, target, body string
		status               int
		want                 string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/kv", "", 200, "[]"},
		{"PUT", "/kv/b", "2", 201, ""},
		{"PUT", "/kv/a", "1", 201, ""},
		{"PUT", "/kv/a", "one", 200, ""},
		{"GET", "/kv/a", "", 200, "one"},
		{"GET", "/kv", "", 200, `["a","b"]`},
		{"POST", "/kv", "", 405, ""},
		{"PATCH", "/kv/a", "", 405, ""},
		{"DELETE", "/kv/a", "", 204, ""},
		{"DELETE", "/kv/a", "", 404, ""},
		{"GET", "/kv/a", "", 404, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/bad.key", "", 400, ""},
		{"GET", "/kv/%41", "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 65), "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 64), "", 404, ""},
		{"GET", "/nope", "", 404, ""},
		{"GET", "/kv/a/", "", 400, ""},
	}
	for _, s := range steps {
		rec := do(t, h, s.method, s.target, s.body)
		if rec.Code != s.status || rec.Body.String() != s.want {
			t.Errorf("%s %s = %d %q, want %d %q", s.method, s.target, rec.Code, rec.Body, s.status, s.want)
		}
	}
}

func TestBinaryValue(t *testing.T) {
	h := New(store.New())
	val := bytes.Repeat([]byte{0, 0xff, 'x', '\n'}, MaxValueLen/4)
	req := httptest.NewRequest("PUT", "/kv/big", bytes.NewReader(val))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Code != 201 {
		t.Fatalf("PUT status %d", rec.Code)
	}
	rec = do(t, h, "GET", "/kv/big", "")
	if !bytes.Equal(rec.Body.Bytes(), val) {
		t.Fatal("value round trip mismatch")
	}

	req = httptest.NewRequest("PUT", "/kv/big", bytes.NewReader(append(val, 1)))
	rec = httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusRequestEntityTooLarge {
		t.Fatalf("oversized PUT status %d, want 413", rec.Code)
	}
}

// Package store implements a concurrency-safe in-memory key-value store.
package store

import (
	"slices"
	"sync"
)

// Store maps string keys to byte values. The zero value is not usable; call New.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// New returns an empty store.
func New() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Put stores val under key, taking ownership of val. It reports whether the
// key was newly created (as opposed to replacing an existing value).
func (s *Store) Put(key string, val []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.data[key]
	s.data[key] = val
	return !exists
}

// Get returns the value stored under key. The returned slice must not be
// modified by the caller.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	delete(s.data, key)
	return ok
}

// Keys returns every key in ascending byte order. The result is never nil.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	for k := range s.data {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

package store

import (
	"slices"
	"testing"
)

func TestStore(t *testing.T) {
	s := New()
	if got := s.Keys(); got == nil || len(got) != 0 {
		t.Fatalf("Keys on empty store = %#v, want empty non-nil slice", got)
	}
	if !s.Put("b", []byte("2")) {
		t.Fatal("first Put should create")
	}
	if s.Put("b", []byte("3")) {
		t.Fatal("second Put should replace")
	}
	s.Put("a", nil)
	if v, ok := s.Get("b"); !ok || string(v) != "3" {
		t.Fatalf("Get(b) = %q, %v", v, ok)
	}
	if got, want := s.Keys(), []string{"a", "b"}; !slices.Equal(got, want) {
		t.Fatalf("Keys = %v, want %v", got, want)
	}
	if !s.Delete("a") || s.Delete("a") {
		t.Fatal("Delete should succeed once")
	}
	if _, ok := s.Get("a"); ok {
		t.Fatal("deleted key still present")
	}
}

// Command app is an in-memory HTTP/1.1 key-value server.
//
// Usage: app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"kvhttp/internal/server"
	"kvhttp/internal/store"
)

func main() {
	if len(os.Args) != 2 {
		usage()
	}
	port, err := strconv.ParseUint(os.Args[1], 10, 16)
	if err != nil || port == 0 {
		usage()
	}
	if err := run(uint16(port)); err != nil {
		log.Fatal(err)
	}
}

func usage() {
	fmt.Fprintf(os.Stderr, "usage: %s <port>\n", os.Args[0])
	os.Exit(2)
}

func run(port uint16) error {
	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(int(port)))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           server.New(store.New()),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       30 * time.Second,
		MaxHeaderBytes:    64 << 10,
		ErrorLog:          log.New(os.Stderr, "http: ", log.LstdFlags),
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := srv.Shutdown(shutdownCtx); err != nil {
			return err
		}
		if err := <-errc; !errors.Is(err, http.ErrServerClosed) {
			return err
		}
		return nil
	}
}
